/**
 * #1177 §2 — the A2 gate: this port agrees with the Go reference implementation.
 *
 * The fixture file is **generated BY the Go implementation**, not written from a
 * second reading of the spec. That distinction is the whole point: a hand-written
 * expectation encodes what I believed `strings.TrimSpace` does, and the two
 * places it does something else are exactly where a port silently diverges.
 *
 * ## The positive control, which @Eli asked for by name
 *
 * A parity suite that loads no fixtures reports success and measures nothing —
 * the failure mode five of us shipped this week (a vacuous mutation runner, a
 * gate walking zero files, an undashed-handle probe). So every section asserts
 * it is non-empty BEFORE it asserts anything about its contents, and the loader
 * throws on a missing or empty file rather than yielding `[]`.
 *
 * ## What is byte-exact and what is not
 *
 * `hash` and the two normalizations are byte-exact against Go, because the hash
 * must be recomputable from a file alone.
 *
 * `render` is NOT, and cannot be: Go's `yaml.v3` writes `'use when:'` where the
 * JS `yaml` package writes `"use when:"`. That is asserted SEMANTICALLY — same
 * frontmatter values, same provenance line, same body — and the provenance line
 * carries the hash, so the part that must agree byte-for-byte is compared
 * byte-for-byte. See `render.ts` for why that is structural rather than a
 * concession.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';
import { parse as parseYaml } from 'yaml';
import { goTrimSpace, normalizeBody, normalizeDescription, runeCount } from './normalize.js';
import { deriveName, validName, validPrefix } from './derive.js';
import { hash } from './hash.js';
import { render } from './render.js';
import { parseFile, SkillFileParseError } from './parse.js';

interface Fixtures {
  sourceCommit: string;
  normalizeDescription: { name: string; in: string; out: string }[];
  normalizeBody: { name: string; in: string; out: string }[];
  deriveName: { name: string; prefix: string; loc: string; out: string }[];
  validName: { name: string; in: string; valid: boolean }[];
  validPrefix: { name: string; in: string; valid: boolean }[];
  hash: {
    name: string; source: string; skillName: string; description: string; content: string; out: string;
  }[];
  render: {
    name: string; source: string; skillName: string; description: string; content: string; out: string;
  }[];
  parseFile: {
    name: string; input: string; err?: boolean; skillName?: string; description?: string;
    source?: string; hash?: string; body?: string; extra?: Record<string, unknown>;
  }[];
}

/** Loads the fixtures, refusing an empty or absent set rather than yielding []. */
function loadFixtures(): Fixtures {
  const path = join(import.meta.dirname, '__fixtures__/skilldoc-fixtures.json');
  const raw = readFileSync(path, 'utf8');
  const f = JSON.parse(raw) as Fixtures;
  const sections: (keyof Fixtures)[] = [
    'normalizeDescription', 'normalizeBody', 'deriveName',
    'validName', 'validPrefix', 'hash', 'render', 'parseFile',
  ];
  for (const s of sections) {
    const v = f[s];
    if (!Array.isArray(v) || v.length === 0) {
      throw new Error(`skilldoc fixtures: section "${String(s)}" is missing or empty — a parity suite that loads nothing passes everything`);
    }
  }
  return f;
}

const F = loadFixtures();

describe('#1177 A2 — the fixture set itself', () => {
  it('POSITIVE CONTROL: every section is populated', () => {
    // Asserted here as well as in the loader so the control is VISIBLE in the
    // run output. A reader scanning for "did the parity suite actually do
    // anything" should not have to trust a helper.
    expect(F.sourceCommit).toBeTruthy();
    expect(F.normalizeDescription.length).toBeGreaterThan(5);
    expect(F.hash.length).toBeGreaterThan(5);
    expect(F.parseFile.length).toBeGreaterThan(3);
  });

  it('carries the two code points a naive port gets wrong, in BOTH directions', () => {
    // The rows that were NOT in the Go suite, which is how a byte-incompatible
    // port would have been declared green. Named explicitly so deleting them
    // is a visible act rather than a quiet shrink of the gate.
    const names = F.normalizeDescription.map((c) => c.name);
    expect(names).toContain('trim-NEL');
    expect(names).toContain('trim-ZWNBSP');
    const astral = F.hash.find((c) => c.name === 'astral-description');
    expect(astral, 'the astral-character hash case').toBeDefined();
  });
});

describe('#1177 A2 — normalization is byte-exact against Go', () => {
  it.each(F.normalizeDescription.map((c) => [c.name, c] as const))(
    'normalizeDescription %s',
    (_n, c) => {
      expect(normalizeDescription(c.in)).toBe(c.out);
    },
  );

  it.each(F.normalizeBody.map((c) => [c.name, c] as const))('normalizeBody %s', (_n, c) => {
    expect(normalizeBody(c.in)).toBe(c.out);
  });

  it('DIVERGES from JS .trim() exactly where Go does, not by accident', () => {
    // The assertion that makes the two trap rows mean something: `.trim()` and
    // `goTrimSpace` must give DIFFERENT answers here. Without this, a future
    // simplification back to `.trim()` would still pass every row above if the
    // fixtures were ever regenerated from the wrong side.
    const nel = 'x';
    expect(goTrimSpace(nel)).toBe('x');
    expect(nel.trim()).not.toBe('x'); // JS does not trim NEL

    const bom = '﻿x﻿';
    expect(goTrimSpace(bom)).toBe(bom); // Go does not trim ZWNBSP
    expect(bom.trim()).toBe('x');
  });

  it('counts code points, not UTF-16 units', () => {
    expect(runeCount('a\u{1F44D}b')).toBe(3);
    expect('a\u{1F44D}b'.length).toBe(4);
  });
});

describe('#1177 A2 — hash is byte-exact against Go', () => {
  it.each(F.hash.map((c) => [c.name, c] as const))('hash %s', (_n, c) => {
    expect(hash(c.source, c.skillName, c.description, c.content)).toBe(c.out);
  });

  it('NUL separation actually separates', () => {
    // `"ab"+"c"` vs `"a"+"bc"` — a boundary shift must not collide. Both rows
    // are in the fixtures; this states the property they exist to prove.
    const a = F.hash.find((c) => c.name === 'nul-separated-boundary')!;
    const b = F.hash.find((c) => c.name === 'nul-separated-boundary-shifted')!;
    expect(a.out).not.toBe(b.out);
  });
});

describe('#1177 — derivation and the grammars', () => {
  it.each(F.deriveName.map((c) => [c.name, c] as const))('deriveName %s', (_n, c) => {
    expect(deriveName(c.prefix, c.loc)).toBe(c.out);
  });
  it.each(F.validName.map((c) => [c.name, c] as const))('validName %s', (_n, c) => {
    expect(validName(c.in)).toBe(c.valid);
  });
  it.each(F.validPrefix.map((c) => [c.name, c] as const))('validPrefix %s', (_n, c) => {
    expect(validPrefix(c.in)).toBe(c.valid);
  });
});

describe('#1177 — render agrees SEMANTICALLY, and on the hash byte-for-byte', () => {
  it.each(F.render.map((c) => [c.name, c] as const))('render %s', (_n, c) => {
    const got = render(c.skillName, c.source, c.description, c.content);

    // The provenance line carries the hash and must match Go exactly.
    const line = (s: string) => /^<!-- hadron-skill .* -->$/m.exec(s)?.[0];
    expect(line(got)).toBe(line(c.out));

    // The frontmatter agrees in VALUE. It cannot agree in bytes: Go's yaml.v3
    // single-quotes where the JS yaml package double-quotes.
    const fm = (s: string) => parseYaml(/^---\n([\s\S]*?)\n---\n/.exec(s)![1]!);
    expect(fm(got)).toEqual(fm(c.out));

    // And the body is identical, which is what the hash is over.
    const body = (s: string) => s.slice(s.indexOf('-->\n\n') + 5);
    expect(body(got)).toBe(body(c.out));
  });

  it('round-trips through parseFile with the hash intact', () => {
    // The invariant @Eli names as the thing to test — the preamble strip is the
    // exact inverse of render — rather than the two functions separately.
    for (const c of F.render) {
      const file = parseFile(render(c.skillName, c.source, c.description, c.content));
      expect(file.source, c.name).toBe(c.source);
      expect(file.name, c.name).toBe(c.skillName);
      expect(file.description, c.name).toBe(normalizeDescription(c.description));
      expect(file.body, c.name).toBe(normalizeBody(c.content));
      // Recomputed from the FILE alone — the property that makes a local edit
      // detectable without the server.
      expect(hash(file.source, file.name, file.description, file.body), c.name).toBe(file.hash);
    }
  });
});

describe('#1177 — parseFile agrees with Go', () => {
  it.each(F.parseFile.map((c) => [c.name, c] as const))('parseFile %s', (_n, c) => {
    if (c.err) {
      expect(() => parseFile(c.input)).toThrow(SkillFileParseError);
      return;
    }
    const got = parseFile(c.input);
    expect(got.name).toBe(c.skillName ?? '');
    expect(got.description).toBe(c.description ?? '');
    expect(got.source).toBe(c.source ?? '');
    expect(got.hash).toBe(c.hash ?? '');
    expect(got.body).toBe(c.body ?? '');
    if (c.extra) expect(got.extra).toEqual(c.extra);
    else expect(got.extra).toBeUndefined();
  });

  it('a legacy header yields a source and NO hash — the whole live corpus', () => {
    // Measured: all 20 provenance files on disk are this shape, which is why
    // the "every existing file classifies locally-edited" risk in the spec
    // cannot fire — they classify `unhashed`, whose action is rewrite.
    const c = F.parseFile.find((x) => x.name === 'legacy-header-is-unhashed')!;
    const got = parseFile(c.input);
    expect(got.source).toBeTruthy();
    expect(got.hash).toBe('');
  });
});
